#include <time.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>

#define CLOCKID CLOCK_REALTIME
#define SIG SIGRTMIN

timer_t global_timerid;
int count = 0;

// Signal handler executed when the timer expires
static void timer_handler(int sig, siginfo_t *si, void *uc) {
    printf("\rTimer expired %d times. Time since start: %lds", ++count, time(NULL));
    fflush(stdout);
}

int setup_timer(void) {
    struct sigaction sa;
    struct sigevent sev;

    // 1. Setup signal handler
    sa.sa_flags = SA_SIGINFO;
    sa.sa_sigaction = timer_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIG, &sa, NULL) == -1) {
        perror("sigaction");
        return -1;
    }

    // 2. Create the timer
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIG;
    sev.sigev_value.sival_ptr = &global_timerid;
    if (timer_create(CLOCKID, &sev, &global_timerid) == -1) {
        perror("timer_create");
        return -1;
    }
    return 0;
}

int main(void) {
    struct itimerspec its;
    struct itimerspec current_time;

    if (setup_timer() != 0) return 1;

    // 3. Set the timer to expire initially in 1.5 seconds, then repeat every 1 second
    its.it_value.tv_sec = 1;       
    its.it_value.tv_nsec = 500000000; // 500 milliseconds
    its.it_interval.tv_sec = 1;    
    its.it_interval.tv_nsec = 0;   

    if (timer_settime(global_timerid, 0, &its, NULL) == -1) {
        perror("timer_settime (start)");
        timer_delete(global_timerid);
        return 1;
    }
    printf("Timer armed. Running for 4 seconds...\n");

    // 4. Demonstrate timer_gettime()
    sleep(1);
    if (timer_gettime(global_timerid, &current_time) == -1) {
        perror("timer_gettime");
    } else {
        printf("Time remaining: %ld.%09ld seconds.\n",
               (long)current_time.it_value.tv_sec, (long)current_time.it_value.tv_nsec);
    }

    sleep(3); // Allow more expirations

    // 5. Disarm the timer (setting it_value to zero)
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 0;
    if (timer_settime(global_timerid, 0, &its, NULL) == -1) {
        perror("timer_settime (disarm)");
    } else {
        printf("\nTimer disarmed.\n");
    }

    // 6. Cleanup
    if (timer_delete(global_timerid) == -1) {
        perror("timer_delete");
        return 1;
    }

    return 0;
}
